#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> first_half;
    vector<int> second_half;
    int max_mod_value = 0;

    int first_half_size = (n / 2) + (n % 2);
    int second_half_size = n / 2;

    // Generate all subset sums for the first half
    for (int subset = 0; subset < (1 << first_half_size); ++subset) {
        int total_sum = 0;
        int mask_value = subset;
        for (int _ = 0; _ < 20; ++_) {
            if (mask_value & 1) {
                total_sum += a[_];
            }
            mask_value >>= 1;
        }
        first_half.push_back(total_sum % m);
    }
    sort(first_half.begin(), first_half.end());

    // Generate all subset sums for the second half
    for (int subset = 0; subset < (1 << second_half_size); ++subset) {
        int total_sum = 0;
        int mask_value = subset;
        for (int _ = 0; _ < 20; ++_) {
            if (mask_value & 1) {
                total_sum += a[first_half_size + _];
            }
            mask_value >>= 1;
        }
        total_sum %= m;

        int target = m - total_sum - 1;
        auto it = lower_bound(first_half.begin(), first_half.end(), target);
        int candidate_value;
        if (it != first_half.end()) {
            candidate_value = *it;
            if (candidate_value > target && it != first_half.begin()) {
                candidate_value = *(--it);
            }
        } else {
            candidate_value = first_half.back();
        }
        max_mod_value = max(max_mod_value, (total_sum + candidate_value) % m);
        max_mod_value = max(max_mod_value, (total_sum + first_half.back()) % m);
    }

    cout << max_mod_value << "\n";

    return 0;
}
